export const meta = {
  name: 'skill-library-analysis',
  description: 'Deep cohesion analysis of the pskoett-skills library: map every skill, analyze via independent lenses, adversarially verify findings, synthesize',
  phases: [
    { title: 'Map', detail: 'parallel deep readers, one per skill cluster' },
    { title: 'Cross-cut', detail: 'independent analytical lenses over the full map' },
    { title: 'Verify', detail: 'adversarially verify material findings against files' },
    { title: 'Synthesize', detail: 'rank tensions, gaps, recommendations' },
  ],
}

const ROOT = '/Users/pepe/Library/CloudStorage/OneDrive-TV2DANMARK/Dokumenter/GitHub/pskoett-skills'

const MAP_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['cluster', 'skills', 'cohesion_notes', 'within_cluster_overlaps'],
  properties: {
    cluster: { type: 'string' },
    skills: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'purpose', 'triggers', 'consumes', 'produces', 'references_out', 'line_count', 'issues'],
        properties: {
          name: { type: 'string' },
          purpose: { type: 'string', description: 'one sentence' },
          triggers: { type: 'string', description: 'when it fires' },
          consumes: { type: 'array', items: { type: 'string' }, description: 'artifacts or upstream skills it depends on' },
          produces: { type: 'array', items: { type: 'string' }, description: 'artifacts/files/signals it emits' },
          references_out: { type: 'array', items: { type: 'string' }, description: 'other skills/agents/files it explicitly points to by name' },
          line_count: { type: 'number' },
          issues: { type: 'array', items: { type: 'string' }, description: 'concrete quality/structure/clarity problems found' },
        },
      },
    },
    cohesion_notes: { type: 'string', description: 'how well these skills hang together as a group' },
    within_cluster_overlaps: { type: 'array', items: { type: 'string' } },
  },
}

const CROSSCUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['lens', 'summary', 'findings'],
  properties: {
    lens: { type: 'string' },
    summary: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['title', 'severity', 'category', 'claim', 'evidence', 'recommendation'],
        properties: {
          title: { type: 'string' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          category: { type: 'string' },
          claim: { type: 'string', description: 'the specific, falsifiable assertion' },
          evidence: { type: 'string', description: 'file paths / quotes backing the claim' },
          recommendation: { type: 'string' },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['verdict', 'evidence', 'notes'],
  properties: {
    verdict: { type: 'string', enum: ['confirmed', 'refuted', 'partial'] },
    evidence: { type: 'string', description: 'what you actually found in the files' },
    notes: { type: 'string' },
  },
}

// ---------- Phase 1: Map ----------
phase('Map')

const CLUSTERS = [
  {
    cluster: 'plan-and-execute',
    paths: ['skills/plan-interview', 'skills/intent-framed-agent', 'skills/context-surfing'],
  },
  {
    cluster: 'verify-and-recover',
    paths: ['skills/verify-gate', 'skills/self-healing', 'skills/self-healing-ci', 'skills/self-healing-workspace'],
  },
  {
    cluster: 'review',
    paths: ['skills/simplify-and-harden', 'skills/simplify-and-harden-ci', 'skills/agent-teams-simplify-and-harden'],
  },
  {
    cluster: 'outer-loop-learning',
    paths: ['skills/self-improvement', 'skills/self-improvement-ci', 'skills/learning-aggregator', 'skills/learning-aggregator-ci', 'skills/pre-flight-check'],
  },
  {
    cluster: 'eval-and-orchestration',
    paths: ['skills/eval-creator', 'skills/eval-creator-ci', 'skills/skill-pipeline', 'skills/skill-tester', 'skills/skill-tester-ci'],
  },
  {
    cluster: 'meta-and-plugin',
    paths: ['.claude/skills/mcp-builder', '.claude/skills/skill-creator', 'plugin/agents', 'plugin/hooks', 'plugin/.claude-plugin', '.claude-plugin', 'README.md', 'CLAUDE.md', 'AGENTS.md'],
  },
]

const mapData = (await parallel(CLUSTERS.map(c => () =>
  agent(
    `You are a skill-library analyst. Repo root: ${ROOT}\n\n` +
    `Deep-read this cluster of skills/files: ${JSON.stringify(c.paths)}\n` +
    `For each skill folder, read its SKILL.md FULLY, and skim any references/, scripts/, assets/ to understand what it actually does (not just what the description claims). For non-skill paths (plugin/agents, hooks, manifests, README/CLAUDE/AGENTS), read them to understand the surrounding wiring.\n\n` +
    `Capture, per skill: one-sentence purpose; trigger conditions; what artifacts/upstream skills it CONSUMES; what it PRODUCES (files, signals, handoffs); every other skill/agent/file it REFERENCES by name (so we can later check those references resolve); SKILL.md line count (wc -l); and concrete ISSUES (over-length, vague triggers, broken/stale references, dead steps, internal contradictions, anything sloppy).\n\n` +
    `Then judge cluster cohesion and note overlaps WITHIN the cluster. Be specific and evidence-based; quote file paths.`,
    { label: `map:${c.cluster}`, phase: 'Map', schema: MAP_SCHEMA }
  )
))).filter(Boolean)

log(`Mapped ${mapData.length} clusters, ${mapData.reduce((n, c) => n + c.skills.length, 0)} skills total`)

// Compact map to feed downstream (drop nothing material, but trim verbosity)
const mapForDownstream = JSON.stringify(mapData)

// ---------- Phase 2: Cross-cut ----------
phase('Cross-cut')

const LENSES = [
  {
    key: 'wiring-integrity',
    prompt:
      `LENS: Wiring & cross-reference integrity.\n` +
      `Every skill names other skills, agents, artifacts, and file paths. Check whether those references actually RESOLVE. ` +
      `In particular: the README/CLAUDE/AGENTS describe a "two-loop" architecture and an inner/outer-loop lifecycle diagram. Verify each named node in those diagrams maps to a real shipping skill or agent (e.g. is "harness-updater" a skill or only a plugin agent? is every artifact path produced by one skill actually consumed by the named downstream skill?). ` +
      `Flag dangling references, handoffs with no receiver, receivers with no producer, and lifecycle-diagram nodes that don't exist as advertised. Read actual files at ${ROOT} to confirm.`,
  },
  {
    key: 'overlap-boundaries',
    prompt:
      `LENS: Overlap & boundary tensions.\n` +
      `Identify pairs/groups of skills whose responsibilities blur or compete. Scrutinize at least: self-healing vs self-improvement (HEALS vs LEARNINGS); simplify-and-harden vs agent-teams-simplify-and-harden vs verify-gate; the interactive-vs-"-ci" duplication pattern across the library (is the split clean or is logic forked/drifting?); skill-pipeline routing vs each skill's own autonomous triggers (do they fight?); intent-framed-agent vs context-surfing concurrent monitoring. ` +
      `For each, state whether the boundary is crisp, documented, and non-overlapping — or muddy. Cite the boundary language each skill uses. Read files at ${ROOT}.`,
  },
  {
    key: 'trigger-quality',
    prompt:
      `LENS: Description & trigger quality / collision.\n` +
      `These skills auto-activate from their description field. Evaluate: are descriptions appropriately scoped (not so broad they over-fire, not so narrow they miss)? Do any two descriptions collide such that the wrong one would fire? Are there descriptions that are bloated (the self-healing description is ~1 paragraph) or that bury the trigger? Which skills would reliably NOT fire when they should? Consider the [Beta] tagging consistency too. Read the frontmatter at ${ROOT}/skills/*/SKILL.md.`,
  },
  {
    key: 'spec-and-sync',
    prompt:
      `LENS: Spec compliance & multi-surface sync.\n` +
      `Check Agent Skills spec + project conventions: name field matches folder name; no README.md inside skill folders; SKILL.md under 500 lines; lowercase-hyphen names. ` +
      `Then check SYNC across surfaces: CLAUDE.md instructs that a "Skill References In This Repo" list be kept in sync across AGENTS.md, CLAUDE.md, and .github/copilot-instructions.md — verify they actually match and that every skill in skills/ is listed. ` +
      `Then check the plugin mirror: does plugin/skills/ contain the same skill set as skills/? Which skills are MISSING from the plugin bundle (e.g. skill-pipeline, skill-tester, self-healing-workspace, simplify-and-harden-ci, etc.)? Are the marketplace manifests (.claude-plugin, .agents, .github/plugin) consistent? Read and diff actual files at ${ROOT}.`,
  },
  {
    key: 'gaps',
    prompt:
      `LENS: Gaps & connective tissue.\n` +
      `Given the stated two-loop architecture, what's structurally MISSING or asymmetric? Examples to evaluate (confirm against files at ${ROOT}, don't assume): the outer-loop "encode" step is an agent (harness-updater) with no interactive skill peer; eval-creator/learning-aggregator have -ci twins but skill-pipeline, pre-flight-check, intent-framed-agent, context-surfing, verify-gate do not — is that intentional or a gap? is there a self-healing-workspace that isn't in the README at all? Does pre-flight-check actually read eval status that eval-creator produces? Is there an orchestrator for the OUTER loop equivalent to skill-pipeline? Identify the highest-value missing pieces and asymmetries.`,
  },
]

const crosscut = (await parallel(LENSES.map(l => () =>
  agent(
    `You are auditing the pskoett-skills library. Here is the structured map of every skill produced by deep readers:\n\n${mapForDownstream}\n\n` +
    `Now apply ONE lens and produce concrete, falsifiable findings. You MAY and SHOULD read actual files under ${ROOT} to ground every claim. Prefer fewer, high-confidence, evidence-backed findings over speculation.\n\n${l.prompt}`,
    { label: `lens:${l.key}`, phase: 'Cross-cut', schema: CROSSCUT_SCHEMA }
  )
))).filter(Boolean)

// Flatten findings, keep material ones for verification
const allFindings = crosscut.flatMap(c => c.findings.map(f => ({ ...f, lens: c.lens })))
const toVerify = allFindings.filter(f => f.severity === 'high' || f.severity === 'medium')
log(`${allFindings.length} findings (${toVerify.length} material → verify)`)

// ---------- Phase 3: Verify ----------
phase('Verify')

const verified = await parallel(toVerify.map((f, i) => () =>
  agent(
    `Adversarially verify this audit claim about the skill library at ${ROOT}. Your job is to REFUTE it if you can — read the actual files and check. Default to "refuted" or "partial" if the evidence doesn't fully hold.\n\n` +
    `TITLE: ${f.title}\nCLAIM: ${f.claim}\nCITED EVIDENCE: ${f.evidence}\n\n` +
    `Open the referenced files yourself and confirm or refute. Report what you actually found.`,
    { label: `verify:${(f.title || 'f').slice(0, 32)}`, phase: 'Verify', schema: VERDICT_SCHEMA }
  ).then(v => ({ finding: f, verdict: v }))
)).then(rs => rs.filter(Boolean))

const confirmed = verified.filter(v => v.verdict.verdict === 'confirmed')
const partial = verified.filter(v => v.verdict.verdict === 'partial')
const refuted = verified.filter(v => v.verdict.verdict === 'refuted')
log(`Verified: ${confirmed.length} confirmed, ${partial.length} partial, ${refuted.length} refuted`)

// ---------- Phase 4: Synthesize ----------
phase('Synthesize')

const synthInput = {
  cluster_cohesion: mapData.map(c => ({ cluster: c.cluster, cohesion_notes: c.cohesion_notes, within_cluster_overlaps: c.within_cluster_overlaps })),
  lens_summaries: crosscut.map(c => ({ lens: c.lens, summary: c.summary })),
  confirmed_findings: confirmed.map(v => ({ ...v.finding, verify_evidence: v.verdict.evidence, verify_notes: v.verdict.notes })),
  partial_findings: partial.map(v => ({ ...v.finding, verify_evidence: v.verdict.evidence, verify_notes: v.verdict.notes })),
  refuted_findings: refuted.map(v => ({ title: v.finding.title, why_refuted: v.verdict.evidence })),
}

const synthesis = await agent(
  `You are the lead reviewer writing the synthesis of a cohesion analysis of the pskoett-skills agent-skill library (repo: ${ROOT}).\n\n` +
  `You are given: per-cluster cohesion notes, per-lens summaries, and findings that have each been adversarially VERIFIED (confirmed / partial / refuted). Treat refuted findings as NOT true — do not repeat them as fact. Build the synthesis only on confirmed + partial findings and the cohesion notes.\n\n` +
  `INPUT:\n${JSON.stringify(synthInput, null, 2)}\n\n` +
  `Write a rigorous synthesis covering:\n` +
  `1. The library's organizing thesis and whether the skills actually realize it (the "two-loop", peak-context philosophy).\n` +
  `2. Cohesion verdict — where the set hangs together well and where it frays.\n` +
  `3. Real tensions/overlaps (boundary problems), each with a crisp resolution.\n` +
  `4. Concrete gaps & asymmetries, ranked by value.\n` +
  `5. A prioritized, specific recommendation list (P0/P1/P2) — each actionable.\n` +
  `Be specific, cite skill names and file paths, and distinguish confirmed from partial confidence. Do not pad. This feeds a human-facing report.`,
  { label: 'synthesis', phase: 'Synthesize' }
)

return {
  counts: {
    clusters: mapData.length,
    skills_mapped: mapData.reduce((n, c) => n + c.skills.length, 0),
    findings_total: allFindings.length,
    confirmed: confirmed.length,
    partial: partial.length,
    refuted: refuted.length,
  },
  refuted_titles: refuted.map(v => v.finding.title),
  confirmed_findings: confirmed.map(v => ({ title: v.finding.title, severity: v.finding.severity, lens: v.finding.lens, claim: v.finding.claim, recommendation: v.finding.recommendation, verify_evidence: v.verdict.evidence })),
  partial_findings: partial.map(v => ({ title: v.finding.title, severity: v.finding.severity, lens: v.finding.lens, verify_notes: v.verdict.notes })),
  synthesis,
}

